import React from 'react';

const links = [
  { label: 'Home', href: '#home' },
  { label: 'Services', href: '#services' },
  { label: 'Why us', href: '#services' },
  { label: 'Blog', href: '#blog' },
  { label: 'Projects', href: '#gallery' },
  { label: 'Enquiry', href: '#enquiry' },
  { label: 'Contact us', href: '#contact' },
];

export default function NavbarSection() {
  return (
    <header className="py-3 shadow-sm bg-white sticky-top">
      <div className="container d-flex flex-wrap align-items-center justify-content-between">
        <a href="#home" className="d-flex align-items-center mb-2 mb-lg-0 text-dark text-decoration-none">
          <span style={{ fontFamily: 'Reenie Beanie, cursive', fontSize: '1.6rem' }}>VAKharche Systems</span>
        </a>
        <nav className="nav">
          {links.map((link) => (
            <a key={link.label} href={link.href} className="nav-link px-2 text-muted">
              {link.label}
            </a>
          ))}
        </nav>
      </div>
    </header>
  );
}
